/* Evidence is kept with the decisions it informs, so a future patch can be reviewed in context. */
(() => {
  "use strict";

  const chapters = [
    {id: "world", label: "Across WoW", title: "Where speedleveling began", introduction: "Early recorded runs show the value of rehearsing a quest circuit. Retail later changed how zones scale, which makes its route timings specific to that version."},
    {id: "classic", label: "2019 Classic", title: "What survives from Classic", introduction: "The August 2019 launch supplies a historical comparison. Later Classic guides map practical quest circuits, while launch reports document what actually happened."},
    {id: "forever", label: "WoW Forever", title: "What changed in Forever", introduction: "Live hotfixes determine how much dungeon kills pay. New destinations, warrior abilities and quest chains change the cost of following an older route."}
  ];

  const sources = [
    {scope:"world", author:"Joana", kind:"Runner’s archive", title:"The original 1–60 speedruns", url:"https://www.joanasworld.com/speedruns/speed-runs.php", note:"Joana documents six attempts and the 4 days 20 hours of played time on Jubei’Thos in 2006. The recorded run used a Horde hunter.", use:"Rehearse the order of objectives and hearth returns. A hunter’s pace is a poor estimate for a shield warrior."},
    {scope:"world", author:"Joana", kind:"Video archive", title:"Watch the recorded route", url:"https://www.joanasworld.com/speedruns/", note:"The runner’s footage records travel, fights and hand-ins as part of the same journey. Its clock measures time in game.", use:"Time a complete circuit, including its return trip. Compare sessions measured on the same clock."},
    {scope:"world", author:"Blizzard", kind:"Official mechanic", title:"Timewalking Campaigns in modern WoW", url:"https://worldofwarcraft.blizzard.com/en-us/news/23529212/the-shadowlands-pre-expansion-patch-arrives-october-13", note:"The Shadowlands pre-patch introduced a new leveling experience with expansion choice and scaling. Retail routing depends on the expansion and patch.", use:"Leave Chromie Time paths out of a Forever itinerary. Transfer the habit of stacking objectives within one area."},
    {scope:"world", author:"Speedrun.com", kind:"Leaderboard categories", title:"Comparing solo, team and assisted runs", url:"https://www.speedrun.com/wow", note:"The retail leveling board separates solo and team brackets and distinguishes questing, seasonal and unrestricted rules. Rankings depend on the category.", use:"Record group status, rested experience and one-time quests when comparing two results. Separate a fast first clear from a sustainable repeat pace."},
    {scope:"classic", author:"Speedrun.com", kind:"Recorded Classic Era run", title:"Tactics’ solo unaided 1–60", url:"https://www.speedrun.com/wowclassicera/runs/zgwddgdy", note:"The board retains a timed solo unaided entry of 88 hours and 14 seconds. This is one Classic Era entry in its own category, separate from the 2019 launch race.", use:"Look for recorded conditions and level splits before using a published time. Use your own recent sessions for the ETA on this character."},
    {scope:"classic", author:"Blizzard", kind:"Launch documentation", title:"What the 2019 release recreated", url:"https://worldofwarcraft.blizzard.com/en-us/news/23090136", note:"Blizzard’s August 2019 FAQ frames Classic as a recreation of the original game as it stood in 2006.", use:"Use 2019 material for original dungeon geography and quest structure. Check each mechanical assumption against Forever."},
    {scope:"classic", author:"PC Gamer", kind:"Launch reporting", title:"Jokerd’s 2019 race to level 60", url:"https://www.pcgamer.com/some-madman-has-already-hit-level-60-in-world-of-warcraft-classic/", note:"Jokerd reached 60 about 79 hours after Classic launched, repeatedly killing packs with a Frost Mage. This was a launch-race result.", use:"Dense camps are worth timing. Smaller pulls that a warrior can sustain can beat larger pulls followed by long recovery."},
    {scope:"classic", author:"Blizzard", kind:"2019 hotfix", title:"The six-player raid XP correction", url:"https://us.forums.blizzard.com/en/wow/t/wow-classic-hotfix-raid-party-xp-bug/282032", note:"On 2 September 2019 Blizzard fixed a bug that had awarded excessive experience to groups of six or more.", use:"Date-check historical dungeon strategies. Some impressive launch-week rates depended on a short-lived bug."},
    {scope:"classic", author:"Hakurai", kind:"2019 video guide", title:"Alliance route from the starting zone to 60", url:"https://www.youtube.com/watch?v=akqzzAA7F08", note:"This May 2019 series lays out Alliance zone transitions, including Hinterlands, Feralas and Tanaris in the high forties. It predates the August launch.", use:"Check the sequence when an older hub still has several nearby quests. Traversing three zones for one remaining objective is rarely worthwhile."},
    {scope:"classic", author:"Icy Veins", kind:"Classic strategy", title:"Quest density, recovery and travel", url:"https://www.icy-veins.com/wow-classic/leveling-guide", note:"The guide counts movement and recovery alongside combat. Its Alliance route visits Un’Goro in the early fifties, followed by Felwood, Winterspring and the Plaguelands.", use:"Keep a solo circuit ready while a group forms. Time from leaving your hub until the turn-in or return, including PvP interruptions."},
    {scope:"classic", author:"Icy Veins", kind:"Classic class guide", title:"Warrior weapon and group considerations", url:"https://www.icy-veins.com/wow-classic/classic-warrior-leveling-guide", note:"The guide documents organized melee dungeon leveling and the importance of a good one-hander for a tank. Its revision history reaches back to the 2019 launch.", use:"Compare any reward with the weapon already equipped. Pursue a guaranteed upgrade on a quest run when it will repay the travel time."},
    {scope:"classic", author:"Wowhead", kind:"Quest geography", title:"Alliance zone options at 40–60", url:"https://www.wowhead.com/classic/guide/alliance-leveling-classic-wow", note:"Feralas, Tanaris and the Hinterlands offer overlapping alternatives around the mid-forties, with Searing Gorge becoming another option.", use:"When a camp is contested, prefer an unfinished nearby hub over a lengthy transfer to a nominally faster zone."},
    {scope:"forever", author:"Blizzard", kind:"Live hotfix · 8 Nov", title:"Dungeon kill experience increased", url:"https://eu.forums.blizzard.com/en/wow/t/dungeon-enemy-xp-increased-8-november/640598", note:"Blizzard increased XP from dungeon kills by 50% relative to the previous Forever value. The change applies to kill XP.", use:"Retest repeat clears. Apply no automatic 50% bonus to total session XP, since travel, waiting and one-time quest rewards change the result."},
    {scope:"forever", author:"Blizzard", kind:"Live hotfix log", title:"Instance resets and repeatable quest rewards", url:"https://news.blizzard.com/en-gb/article/24315281/wow-forever-hotfixes-november-25-2026", note:"On 20 November Blizzard limited resets and entries to five per dungeon per hour. The same rolling log removes XP from repeat turn-ins of Water Pouch Bounty.", use:"Exclude repeat water-pouch turn-ins from a Tanaris XP plan. Account for the reset limit before planning a string of partial clears."},
    {scope:"forever", author:"Blizzard", kind:"Live hotfix · 14 Nov", title:"The corrected 12-level dungeon rule", url:"https://us.forums.blizzard.com/en/wow/t/player-level-dungeon-xp-adjustment-november-14/2416343/1", note:"Blizzard revised its 13 November change. A dungeon kill awards zero XP to the party if any member is more than 12 levels above that enemy.", use:"Check the highest player against the lowest mobs on the intended path. A level 60 member triggers the cutoff on level 47 enemies, but level 48 clears this particular test."},
    {scope:"forever", author:"Blizzard", kind:"Class design", title:"Warrior changes for Forever", url:"https://news.blizzard.com/en-us/article/24301514/world-of-warcraft-forever-class-deep-dives-priest-and-warrior", note:"Victory Rush gives an attack and 10% maximum-health heal after a non-trivial kill. The 16-point Protection talent Vanguard enables Charge in Defensive Stance.", use:"Use Victory Rush while moving through safe melee targets. With Vanguard selected, open in Defensive Stance and preserve momentum."},
    {scope:"forever", author:"Blizzard", kind:"Dungeon brackets", title:"Nine new five-player dungeons", url:"https://worldofwarcraft.blizzard.com/en-us/news/24301455", note:"Alcaz Prison is listed at 48–53, Blackmaw Hold at 55–60 and Shaper’s Terrace at 58–60. Each opens another option beyond the 2019 circuit.", use:"Try a new dungeon when your group, travel and outstanding quests align. The advertised level band establishes suitability, not a speed record."},
    {scope:"forever", author:"Blizzard", kind:"Official mechanic", title:"Camps, repairs and field preparation", url:"https://worldofwarcraft.blizzard.com/en-us/news/24301516/gather-around-the-campfire-in-world-of-warcraft-forever", note:"Forever expands the Cooking Fire into a shared campsite with profession features. A conveniently placed camp can consolidate preparation during a leveling circuit.", use:"Use a camp you pass for preparation when it saves a town trip. Include setup time if testing the route with a camp."},
    {scope:"forever", author:"Blizzard", kind:"Ruleset design", title:"How the PvP ruleset works", url:"https://worldofwarcraft.blizzard.com/en-us/news/24302070", note:"Forever organizes characters by regional ruleset. On a PvP ruleset, an outdoor quest circuit can be disrupted by the opposing faction.", use:"Keep travel and corpse runs on the session clock. The 05:00 Brussels slot is a personal schedule, with no assumed population or queue length."},
    {scope:"forever", author:"AOTC", kind:"Observed race", title:"First-to-60 completion records", url:"https://www.aotc.gg/forever/first-to-60", note:"The tracker lists Ahmp Ahmpy as the first recorded warrior at 60 on 7 November. The character finished with Team Ahmpy on US PvP.", use:"A coordinated team can finish together. This timestamp gives neither a solo Protection benchmark nor a measured XP/hour for level 46."},
    {scope:"forever", author:"Icy Veins", kind:"Class guide", title:"Protection Warrior leveling priorities", url:"https://www.icy-veins.com/wow-forever/protection-warrior-leveling", note:"The November guide prioritizes Shield Slam and Revenge, uses Shield Block against melee and notes Thunder Clap’s four-target limit.", use:"Favor Revenge when rage is low. In groups, spread attacks to enemies Thunder Clap misses. Count healing stops when testing solo pull sizes."},
    {scope:"forever", author:"Icy Veins", kind:"Quest guide", title:"Three Gadgetzan pickups for Zul’Farrak", url:"https://www.icy-veins.com/wow-forever/zul-farrak-quests", note:"Scarab Shells, Troll Temper and Divino-matic Rod all start in Gadgetzan and require level 40. Two depend on drops and can take more than one clear.", use:"At 46, collect any unfinished pickups together. Check the party for a Mallet before adding the separate Gahz’rilla objective."},
    {scope:"forever", author:"Icy Veins", kind:"Quest guide", title:"Maraudon and the Thrash Blade reward", url:"https://www.icy-veins.com/wow-forever/maraudon-quests", note:"Keeper Marandis in Nijel’s Point offers the Alliance version of Corruption of Earth and Seed from level 45. Killing Princess Theradras unlocks a choice including Thrash Blade.", use:"Confirm the group is actually going to Princess before travelling. The quest minimum is earlier than a comfortable full clear for many groups."},
    {scope:"forever", author:"Icy Veins", kind:"Quest guide", title:"Alliance quest access for Alcaz Prison", url:"https://www.icy-veins.com/wow-forever/alcaz-prison-quests", note:"The Secret Prison is available from 48 after the chain starting with Our Man in Theramore. Its first step must be handed in before killing The Questioner.", use:"Check the prerequisite before making the Dustwallow trip. Tell the group about the quest order before the boss pull."},
    {scope:"forever", author:"Icy Veins", kind:"Quest guide", title:"Plan a single Blackrock Depths wing", url:"https://www.icy-veins.com/wow-forever/blackrock-depths-quests", note:"The Alliance Windsor chain visits the prison and requires leaving the instance between stages. A party advertising BRD may have different objectives.", use:"Agree on prison, arena or deeper bosses before departing. A specific stopping point makes a short morning run feasible."},
    {scope:"forever", author:"Realm First", kind:"Client data", title:"XP required from 46 to 60", url:"https://realmfirst.net/world-of-warcraft-forever/leveling-guide/wow-forever-xp-per-level/", note:"The November client table gives 123,200 XP from 46 to 47, 209,800 from 59 to 60 and 4,084,700 XP for the full journey from 1 to 60.", use:"A fresh 46 has 2,307,200 XP left. Subtract the XP already on the bar, then divide by a recent, comparable measured pace."},
    {scope:"forever", author:"Wowhead", kind:"XP calculator", title:"Check a level’s experience threshold", url:"https://www.wowhead.com/forever/experience-calculator?level=46", note:"The Forever calculator applies the original 1–60 curve. Its level display lets you cross-check the bar thresholds and how they grow at higher levels.", use:"If a session spans a level-up, add the remaining portion of the first bar and the earned portion of the next."},
    {scope:"forever", author:"Polestar", kind:"Community route", title:"Tanaris quest circuit for Alliance 46–48", url:"https://polestar.guide/guides/alliance/40-50/04-tanaris", note:"Polestar’s November route includes the Dunemaul compound and Pirate Hats Ahoy! among several Tanaris objectives. Its entire 46–48 itinerary also visits multiple distant zones.", use:"Test the southern Dunemaul ogres on a short circuit while recruiting in Tanaris. Keep the overseas stages for a longer session if they are still worthwhile."},
    {scope:"forever", author:"NOHITJEROME", kind:"Creator demonstration", title:"Grinding spots in the forties", url:"https://www.youtube.com/watch?v=OV8ZSM62r4Y&t=405s", note:"The creator’s 22 November video introduces his recommendation tool and discusses 40–50 grinding spots from 6:45. Its recommendations are candidates for a local trial.", use:"Time one camp for 15 minutes, counting eating and respawn waits. Run a second sample after the first quest hand-in to check sustainable kill XP."},
    {scope:"forever", author:"NOHITJEROME", kind:"Unverified listing", title:"The level 46 grind calculator", url:"https://nohitjerome.com/wow-forever/grind/level-46/", note:"The individual level-46 listing was unavailable during review. Its specific camps, rates and sample conditions could not be verified. The linked creator video documents the tool.", use:"Treat displayed rates as unverified estimates until reproduced on Laymer. The independently documented Dunemaul route gives you a comparison in the same region."},
    {scope:"forever", author:"Wowhead", kind:"Professions guide", title:"Gathering on a speedleveling route", url:"https://www.wowhead.com/forever/guide/wow-forever-profession-pairings-by-class-35082", note:"Gathering produces saleable materials while leveling. Sale prices, time reaching a node and the value of any gear upgrade determine the practical return.", use:"For a speed-first session, mine a visible node only when its detour pays for something that advances 60. At 24,000 XP/h a five-minute detour costs roughly 2,000 XP of progress."},
    {scope:"forever", author:"RestedXP", kind:"Guide publisher", title:"Speedrun and Legacy guide goals", url:"https://shop.restedxp.com/forever/", note:"The publisher distinguishes its speed route from a Legacy-completion route. This describes the product’s intent and does not establish a measured saving for Protection.", use:"When the guide asks for a rare drop, time its mob circuit separately. Move on when a nearby quest circuit repeatedly earns more XP/hour."}
  ];

  const decisions = [
    {title:"At level 46", text:"Pick up the three Gadgetzan dungeon quests you still need. If a level-appropriate group is ready, tank Zul’Farrak and include the hand-ins in your first-clear total.", ref:"https://www.icy-veins.com/wow-forever/zul-farrak-quests", link:"Zul’Farrak quest locations"},
    {title:"While a group forms", text:"Quest nearby from Gadgetzan or Steamwheedle Port. If you are still in Feralas, finish the current cluster before crossing the map for an unconfirmed group.", ref:"https://www.icy-veins.com/wow-classic/leveling-guide", link:"Classic Alliance route"},
    {title:"Before repeating", text:"Time the entire clear, including recruitment, travel and recovery. For example, 18,000 XP over 45 minutes is 24,000 XP/h. Repeat only if it beats your recent solo pace.", ref:"https://eu.forums.blizzard.com/en/wow/t/dungeon-enemy-xp-increased-8-november/640598", link:"Dungeon XP change"}
  ];

  const escape = value => value.replace(/[&<>"']/g, char => ({"&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;"}[char]));
  const external = (url, label) => '<a class="lib-link" target="_blank" rel="noopener noreferrer" href="' + escape(url) + '">' + escape(label) + ' <span aria-hidden="true">↗</span></a>';
  const searchGlyph = '<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="10.6" cy="10.6" r="6.6"></circle><path d="m16 16 5 5"></path></svg>';

  function render(host) {
    let scope = "all";
    host.innerHTML = '<div class="atlas-library"><header class="lib-header"><p class="lib-kicker">FIELD RESEARCH</p><h1>Research library</h1><p>From the original race to 60 to a one-hour morning on US PvP. Explore the evidence behind Laymer’s route.</p></header>' +
      '<section class="lib-brief" aria-labelledby="lib-brief-title"><div class="lib-brief-head"><div class="lib-mini">PROTECTION WARRIOR <span> / </span> US PVP</div><h2 id="lib-brief-title">What to do with the evidence</h2></div><div class="lib-decisions">' +
      decisions.map(d => '<div><h3>' + escape(d.title) + '</h3><p>' + escape(d.text) + '</p>' + external(d.ref,d.link) + '</div>').join('') +
      '</div></section><section aria-labelledby="lib-sources-title"><div class="lib-sources-head"><div><div class="lib-mini">ANNOTATED SOURCES</div><h2 id="lib-sources-title">The reading room</h2></div><span class="lib-date">Reviewed 26 Nov 2026</span></div>' +
      '<div class="lib-controls"><div class="lib-filters" role="group" aria-label="Filter by game version">' +
      [{id:"all",label:"All sources"}, ...chapters].map(b => '<button type="button" data-scope="'+b.id+'" aria-pressed="'+(b.id==='all')+'">'+escape(b.label)+'</button>').join('') +
      '</div><label class="lib-search">'+searchGlyph+'<input type="search" placeholder="Search sources…" aria-label="Search sources"></label></div><p class="lib-count" role="status" aria-live="polite"></p><div class="lib-results"></div></section></div>';
    const root = host.querySelector('.atlas-library');
    const search = root.querySelector('input');
    const filters = root.querySelectorAll('[data-scope]');
    const results = root.querySelector('.lib-results');
    const tidy = value => value.toLocaleLowerCase().replace(/[’']/g,"");
    function refresh() {
      const query = tidy(search.value.trim());
      const words = query.split(/\s+/).filter(Boolean);
      const matches = sources.filter(s => {
        if(scope !== "all" && scope !== s.scope) return false;
        const haystack = tidy([s.author,s.kind,s.title,s.note,s.use,chapters.find(ch => ch.id===s.scope).label].join(" "));
        return words.every(w => haystack.includes(w));
      });
      filters.forEach(b => b.setAttribute("aria-pressed",String(b.dataset.scope === scope)));
      root.querySelector('.lib-count').textContent = matches.length + (matches.length===1 ? " source" : " sources");
      if(!matches.length){
        results.innerHTML='<div class="lib-empty"><h3>No matching sources</h3><p>Try a game version, dungeon, class ability or publisher.</p><button type="button">Clear filters</button></div>';
        results.querySelector('button').addEventListener('click',()=>{scope="all"; search.value=""; refresh(); search.focus();});
        return;
      }
      results.innerHTML = chapters.map(ch => {
        const items = matches.filter(s => s.scope===ch.id);
        if(!items.length) return "";
        return '<section class="lib-chapter"><div class="lib-chapter-intro"><span class="lib-mini">'+escape(ch.label)+'</span><h3>'+escape(ch.title)+'</h3><p>'+escape(ch.introduction)+'</p></div><div class="lib-entries">' +
        items.map(s => '<details class="lib-entry"><summary><div class="lib-source-meta"><span>'+escape(s.author)+'</span><em>'+escape(s.kind)+'</em></div><strong>'+escape(s.title)+'</strong><span class="lib-chevron" aria-hidden="true"></span></summary><div class="lib-annotation"><p>'+escape(s.note)+'</p><p><b>For Laymer</b> '+escape(s.use)+'</p>'+external(s.url,"Read source")+'</div></details>').join('') +
        '</div></section>';
      }).join('');
    }
    filters.forEach(b => b.addEventListener('click',()=>{scope=b.dataset.scope; refresh();}));
    search.addEventListener('input',refresh);
    refresh();
  }
  window.Library = {render};
})();
